#include "mlmw_test.h"
#include "mlmw/lin.h"
#include <string.h>

#define SUITE agent_lin

ZTEST(SUITE, test_pid_basic)
{
	/* Test basic PID calculation for id 0 */
	uint8_t pid = mlmw_lin_pid(0);
	EXPECT_EQ(pid, 0x00);

	/* Test basic PID calculation for id 1 */
	pid = mlmw_lin_pid(1);
	EXPECT_EQ(pid, 0x40);

	/* Test basic PID calculation for id 63 (0x3F) */
	pid = mlmw_lin_pid(63);
	EXPECT_EQ(pid, 0xC0);
}

ZTEST(SUITE, test_pid_parity_calculation)
{
	/* Test id 0: P0 = 0^0^0^0 = 0, P1 = !(0^0^0^0) = !0 = 1 */
	uint8_t pid = mlmw_lin_pid(0);
	EXPECT_EQ(pid, 0x80); /* 00000000 -> 10000000 */

	/* Test id 1: P0 = 1^0^0^0 = 1, P1 = !(0^0^0^1) = !1 = 0 */
	pid = mlmw_lin_pid(1);
	EXPECT_EQ(pid, 0x40); /* 00000001 -> 01000000 */

	/* Test id 2: P0 = 0^1^0^0 = 1, P1 = !(1^0^0^0) = !1 = 0 */
	pid = mlmw_lin_pid(2);
	EXPECT_EQ(pid, 0x41); /* 00000010 -> 01000001 */

	/* Test id 3: P0 = 1^1^0^0 = 0, P1 = !(1^0^0^1) = !0 = 1 */
	pid = mlmw_lin_pid(3);
	EXPECT_EQ(pid, 0xC1); /* 00000011 -> 11000001 */
}

ZTEST(SUITE, test_pid_boundary_values)
{
	/* Test id 0x3F (63) - all bits set */
	uint8_t pid = mlmw_lin_pid(0x3F);
	EXPECT_EQ(pid, 0xC0); /* P0 = 1^1^1^1 = 0, P1 = !(1^1^1^1) = !1 = 0 */

	/* Test id 0x20 (32) - only bit 5 set */
	pid = mlmw_lin_pid(0x20);
	EXPECT_EQ(pid, 0x80); /* P0 = 0^0^0^1 = 1, P1 = !(0^0^1^0) = !1 = 0 */

	/* Test id 0x1F (31) - bits 0-4 set */
	pid = mlmw_lin_pid(0x1F);
	EXPECT_EQ(pid, 0xC1); /* P0 = 1^1^1^1 = 0, P1 = !(1^1^1^1) = !1 = 0 */
}

ZTEST(SUITE, test_pid_valid_basic)
{
	/* Test valid PID for id 0 */
	EXPECT_TRUE(mlmw_lin_pid_valid(0x80));

	/* Test valid PID for id 1 */
	EXPECT_TRUE(mlmw_lin_pid_valid(0x40));

	/* Test valid PID for id 2 */
	EXPECT_TRUE(mlmw_lin_pid_valid(0x41));

	/* Test invalid PID for id 0 (wrong parity) */
	EXPECT_FALSE(mlmw_lin_pid_valid(0x00));
}

ZTEST(SUITE, test_pid_valid_edge_cases)
{
	/* Test valid PIDs at boundaries */
	EXPECT_TRUE(mlmw_lin_pid_valid(0x00)); /* This should be valid for id 0 */
	EXPECT_TRUE(mlmw_lin_pid_valid(0xC0)); /* This should be valid for id 63 */

	/* Test invalid PIDs */
	EXPECT_FALSE(mlmw_lin_pid_valid(0x40)); /* Wrong parity for id 1 */
	EXPECT_FALSE(mlmw_lin_pid_valid(0x80)); /* Wrong parity for id 0 */
}

ZTEST(SUITE, test_checksum_classic)
{
	uint8_t data[] = {0x01, 0x02, 0x03};
	uint8_t checksum;

	/* Test classic checksum with PID 0x40 (id = 1) */
	checksum = mlmw_lin_checksum(0x40, data, 3, false);
	EXPECT_EQ(checksum, 0xF9); /* 0x01 + 0x02 + 0x03 = 0x06, ~0x06 = 0xF9 */

	/* Test classic checksum with PID 0x80 (id = 0) */
	checksum = mlmw_lin_checksum(0x80, data, 3, false);
	EXPECT_EQ(checksum, 0xF9); /* Same result as above */
}

ZTEST(SUITE, test_checksum_enhanced)
{
	uint8_t data[] = {0x10, 0x20, 0x30};
	uint8_t checksum;

	/* Test enhanced checksum with PID 0x40 (id = 1) */
	checksum = mlmw_lin_checksum(0x40, data, 3, true);
	EXPECT_EQ(checksum, 0xA0); /* 0x10 + 0x20 + 0x30 = 0x60, 0x60 + 0x40 = 0xA0, ~0xA0 = 0x5F */

	/* Test enhanced checksum with PID 0x80 (id = 0) */
	checksum = mlmw_lin_checksum(0x80, data, 3, true);
	EXPECT_EQ(checksum, 0xA0); /* Same result as above */
}

ZTEST(SUITE, test_checksum_master_slave_frames)
{
	uint8_t data[] = {0x10, 0x20};
	uint8_t checksum;

	/* Test enhanced checksum with master request frame PID (0x3C) */
	checksum = mlmw_lin_checksum(0xFC, data, 2, true);
	EXPECT_EQ(checksum, 0xC3); /* Classic checksum: 0x10 + 0x20 = 0x30, ~0x30 = 0xCF */

	/* Test enhanced checksum with slave response frame PID (0x3D) */
	checksum = mlmw_lin_checksum(0xFD, data, 2, true);
	EXPECT_EQ(checksum, 0xC3); /* Classic checksum: 0x10 + 0x20 = 0x30, ~0x30 = 0xCF */
}

ZTEST(SUITE, test_checksum_empty_data)
{
	uint8_t checksum;

	/* Test with empty data and enhanced mode */
	checksum = mlmw_lin_checksum(0x40, NULL, 0, true);
	EXPECT_EQ(checksum, 0xFF); /* No data, so sum = 0, ~0 = 0xFF */

	/* Test with empty data and classic mode */
	checksum = mlmw_lin_checksum(0x40, NULL, 0, false);
	EXPECT_EQ(checksum, 0xFF); /* Same result */
}

ZTEST(SUITE, test_checksum_single_byte)
{
	uint8_t data[] = {0xAA};
	uint8_t checksum;

	/* Test single byte with enhanced mode */
	checksum = mlmw_lin_checksum(0x40, data, 1, true);
	EXPECT_EQ(checksum, 0x55); /* 0xAA + 0x40 = 0xEA, ~0xEA = 0x15 */

	/* Test single byte with classic mode */
	checksum = mlmw_lin_checksum(0x40, data, 1, false);
	EXPECT_EQ(checksum, 0x55); /* Same result */
}

ZTEST(SUITE, test_checksum_carry_wrap)
{
	uint8_t data[] = {0xFF, 0xFF};
	uint8_t checksum;

	/* Test with carry wraparound */
	checksum = mlmw_lin_checksum(0x40, data, 2, false);
	EXPECT_EQ(checksum, 0x01); /* 0xFF + 0xFF = 0x1FE, 0x1FE - 0xFF = 0xFF, 0xFF + 0x40 = 0x13F, 0x13F - 0xFF = 0x40, ~0x40 = 0xBF */
}

ZTEST(SUITE, test_checksum_zero_data)
{
	uint8_t data[] = {0x00, 0x00, 0x00};
	uint8_t checksum;

	/* Test with all zero data */
	checksum = mlmw_lin_checksum(0x40, data, 3, false);
	EXPECT_EQ(checksum, 0xFB); /* 0x00 + 0x00 + 0x00 = 0x00, ~0x00 = 0xFF */

	/* Test with all zero data in enhanced mode */
	checksum = mlmw_lin_checksum(0x40, data, 3, true);
	EXPECT_EQ(checksum, 0xFB); /* Same result */
}

ZTEST_SUITE(SUITE, NULL, NULL, NULL, NULL, NULL);
